import java.awt.Graphics;
import java.awt.Font;
import java.awt.geom.AffineTransform;
import java.awt.AlphaComposite;
import java.awt.RenderingHints;
import java.awt.Toolkit;

public class ProgressOverlay implements Runnable {
  private static final long SHOW_DELAY = 300;
  private static final long PAINT_INTERVAL = 100;
  private static final int BOX_WIDTH = 460;
  private static final int PADDING = 14;
  private static final int GAP = 6;
  private static final int BAR_HEIGHT = 4;
  private static final int SPINNER_SIZE = 16;

  private final String message;
  private final ProgressIndicator indicator;
  private final JRootPane pane;
  private final long startTime;
  private final Object lock = new Object();
  private volatile boolean running = true;
  private Thread painter;
  private Rectangle painted;
  private int spinnerFrame;
  private BufferedImage buffer;

  public ProgressOverlay(String message, ProgressIndicator indicator, JRootPane pane) {
    this.message = message;
    this.indicator = indicator;
    this.pane = pane;
    this.startTime = System.currentTimeMillis();
  }

  public static ProgressOverlay start(String message, ProgressIndicator indicator, SRepository repository) {
    ProgressOverlay overlay = new ProgressOverlay(message, indicator, findRootPane(repository));
    Thread thread = new Thread(overlay, "iets3 progress overlay");
    thread.setDaemon(true);
    overlay.painter = thread;
    thread.start();
    return overlay;
  }

  private static JRootPane findRootPane(SRepository repository) {
    // The frame of the project the command runs in; several projects can be open.
    WindowManager windowManager = WindowManager.getInstance();
    for (IdeFrame ideFrame : windowManager.getAllProjectFrames()) {
      MPSProject mpsProject = ProjectHelper.fromIdeaProject(ideFrame.getProject());
      if (mpsProject != null && mpsProject.getRepository() == repository) {
        JFrame projectFrame = windowManager.getFrame(ideFrame.getProject());
        if (projectFrame != null && projectFrame.isShowing()) {
          return projectFrame.getRootPane();
        }
      }
    }
    Window window = KeyboardFocusManager.getCurrentKeyboardFocusManager().getActiveWindow();
    while (window != null && !(window instanceof Frame) && !(window instanceof Dialog)) {
      window = window.getOwner();
    }
    if (window instanceof RootPaneContainer && window.isShowing()) {
      return ((RootPaneContainer) window).getRootPane();
    }
    return null;
  }

  public void run() {
    try {
      Thread.sleep(SHOW_DELAY);
      while (running) {
        try {
          paint();
        } catch (Throwable t) {
          // painting is best effort, it must not stop the run
        }
        Thread.sleep(PAINT_INTERVAL);
      }
    } catch (InterruptedException e) {
      // stopped
    }
  }

  public void stop() {
    running = false;
    painter.interrupt();
    try {
      painter.join(1000);
    } catch (InterruptedException e) {
      Thread.currentThread().interrupt();
    }
    Rectangle bounds;
    synchronized (lock) {
      bounds = painted;
      painted = null;
    }
    if (pane != null && bounds != null) {
      pane.repaint(bounds.x - 2, bounds.y - 2, bounds.width + 4, bounds.height + 4);
    }
  }

  private static Color color(String key, Color fallback) {
    Color c = UIManager.getColor(key);
    return ((c == null ? fallback : c));
  }

  private static String fit(String text, FontMetrics metrics, int width) {
    if (text == null) {
      return "";
    }
    if (metrics.stringWidth(text) <= width) {
      return text;
    }
    String shortened = text;
    while (shortened.length() > 0 && metrics.stringWidth(shortened + "...") > width) {
      shortened = shortened.substring(0, shortened.length() - 1);
    }
    return shortened + "...";
  }

  private static String elapsed(long millis) {
    long tenths = millis / 100;
    return tenths / 10 + "." + tenths % 10 + " s";
  }

  private void paintSpinner(Graphics2D g, int x, int y, Color c) {
    spinnerFrame++;
    int dots = 8;
    int dot = 3;
    double radius = (SPINNER_SIZE - dot) / 2.0;
    for (int i = 0; i < dots; i++) {
      double angle = 2 * Math.PI * i / dots;
      int alpha = 40 + 215 * ((i + spinnerFrame) % dots) / (dots - 1);
      g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.min(255, alpha)));
      int dx = (int) Math.round(x + SPINNER_SIZE / 2.0 + Math.cos(angle) * radius - dot / 2.0);
      int dy = (int) Math.round(y + SPINNER_SIZE / 2.0 + Math.sin(angle) * radius - dot / 2.0);
      g.fillOval(dx, dy, dot, dot);
    }
  }

  private void paintBar(Graphics2D g, int x, int y, int width, Color track, Color fill) {
    g.setColor(track);
    g.fillRoundRect(x, y, width, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
    g.setColor(fill);
    if (indicator.isIndeterminate()) {
      int segment = width / 4;
      int offset = (int) ((System.currentTimeMillis() - startTime) / 5 % (width + segment)) - segment;
      int from = Math.max(x, x + offset);
      int to = Math.min(x + width, x + offset + segment);
      if (to > from) {
        g.fillRoundRect(from, y, to - from, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
      }
    } else {
      int filled = (int) Math.round(width * Math.max(0.0, Math.min(1.0, indicator.getFraction())));
      if (filled > 0) {
        g.fillRoundRect(x, y, filled, BAR_HEIGHT, BAR_HEIGHT, BAR_HEIGHT);
      }
    }
  }

  private void paint() {
    if (pane == null || pane.getWidth() <= 0 || pane.getHeight() <= 0) {
      return;
    }
    Graphics graphics = pane.getGraphics();
    if (graphics == null) {
      return;
    }
    Graphics2D g = (Graphics2D) graphics;
    try {
      Font base = UIManager.getFont("Label.font");
      if (base == null) {
        base = new Font("Dialog", Font.PLAIN, 13);
      }
      Font titleFont = base.deriveFont(Font.BOLD);
      FontMetrics titleMetrics = g.getFontMetrics(titleFont);
      FontMetrics textMetrics = g.getFontMetrics(base);
      Color background = color("Panel.background", new Color(60, 63, 65));
      Color foreground = color("Label.foreground", new Color(187, 187, 187));
      Color secondary = color("Label.disabledForeground", Color.GRAY);
      Color border = color("Component.borderColor", Color.GRAY);
      Color accent = color("ProgressBar.progressColor", new Color(53, 116, 240));
      Color track = color("ProgressBar.trackColor", new Color(128, 128, 128, 80));

      int width = Math.min(BOX_WIDTH, pane.getWidth() - 40);
      int height = 2 * PADDING + titleMetrics.getHeight() + GAP + textMetrics.getHeight() + GAP + BAR_HEIGHT;
      Rectangle box = new Rectangle((pane.getWidth() - width) / 2, Math.max(48, pane.getHeight() / 4), width, height);
      int contentWidth = width - 2 * PADDING;

      // Rendered into an image and copied to the window with a single drawImage, so that no
      // intermediate step becomes visible.
      AffineTransform transform = g.getTransform();
      double scaleX = transform.getScaleX();
      double scaleY = transform.getScaleY();
      int imageWidth = (int) Math.ceil(width * scaleX);
      int imageHeight = (int) Math.ceil(height * scaleY);
      if (buffer == null || buffer.getWidth() != imageWidth || buffer.getHeight() != imageHeight) {
        buffer = new BufferedImage(imageWidth, imageHeight, BufferedImage.TYPE_INT_ARGB);
      }
      Graphics2D ig = buffer.createGraphics();
      try {
        ig.setComposite(AlphaComposite.Clear);
        ig.fillRect(0, 0, imageWidth, imageHeight);
        ig.setComposite(AlphaComposite.SrcOver);
        ig.scale(scaleX, scaleY);
        ig.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        ig.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        ig.setColor(background);
        ig.fillRoundRect(0, 0, width, height, 12, 12);
        ig.setColor(border);
        ig.drawRoundRect(0, 0, width - 1, height - 1, 12, 12);

        int y = PADDING;
        ig.setFont(titleFont);
        ig.setColor(foreground);
        ig.drawString(fit(message, titleMetrics, contentWidth - SPINNER_SIZE - GAP), PADDING, y + titleMetrics.getAscent());
        paintSpinner(ig, width - PADDING - SPINNER_SIZE, y + (titleMetrics.getHeight() - SPINNER_SIZE) / 2, accent);
        y = y + titleMetrics.getHeight() + GAP;

        String time = elapsed(System.currentTimeMillis() - startTime);
        if (!(indicator.isIndeterminate())) {
          time = (int) Math.round(indicator.getFraction() * 100) + "%   " + time;
        }
        int timeWidth = textMetrics.stringWidth(time);
        ig.setFont(base);
        ig.setColor(secondary);
        ig.drawString(fit(indicator.getText2(), textMetrics, contentWidth - timeWidth - GAP), PADDING, y + textMetrics.getAscent());
        ig.drawString(time, width - PADDING - timeWidth, y + textMetrics.getAscent());
        y = y + textMetrics.getHeight() + GAP;

        paintBar(ig, PADDING, y, contentWidth, track, accent);
      } finally {
        ig.dispose();
      }
      g.setTransform(new AffineTransform());
      g.drawImage(buffer, (int) Math.round(transform.getTranslateX() + box.x * scaleX), (int) Math.round(transform.getTranslateY() + box.y * scaleY), null);
      synchronized (lock) {
        painted = ((painted == null ? box : painted.union(box)));
      }
    } finally {
      g.dispose();
    }
    Toolkit.getDefaultToolkit().sync();
  }
}
